    write(P / 'GRAPH_FEEDBACK.json', feedback)
    write(P / 'GRAPH_COVERAGE_PROPOSAL.json', dict(proposed_id='DENT-VAL-BITE-FINDING-SCREENING', status='PROPOSAL_ONLY', existing_goal='DENT-GOAL', source_artifacts=[_release_expand('X7'), _release_expand('X21'), _release_expand('X50')], missing_quantities=['source-polarity by tooth/region', 'sensitivity at fixed specificity by finding', 'conditional named-reader positive/negative agreement', 'pose-repeat error budget'], edges=[dict(from_quantity='registered tooth-region geometry and clinician region statement', to_quantity='finding-specific screening and referral research evaluation', resolution='PER_TOOTH/PER_SURFACE_REGION', timescale='SIMULTANEOUS')]))
